import urllib.request,urllib.parse,json,socket,base64,os,struct,time

def new_page(url):
 r=urllib.request.Request('http://localhost:9222/json/new?'+urllib.parse.quote(url,safe=':/'),method='PUT')
 return json.load(urllib.request.urlopen(r))

def recv_exact(s,n):
 b=b''
 while len(b)<n:
  x=s.recv(n-len(b))
  if not x: raise EOFError
  b+=x
 return b

class CDP:
 def __init__(self,url):
  u=urllib.parse.urlparse(url); self.s=socket.create_connection((u.hostname,u.port)); k=base64.b64encode(os.urandom(16)).decode()
  req=f'GET {u.path} HTTP/1.1\r\nHost: {u.netloc}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {k}\r\nSec-WebSocket-Version: 13\r\nOrigin: http://localhost\r\n\r\n'
  self.s.sendall(req.encode()); data=b''
  while b'\r\n\r\n' not in data:data+=self.s.recv(4096)
  self.i=0
 def send(self,m,p={}):
  self.i+=1; payload=json.dumps({'id':self.i,'method':m,'params':p}).encode(); n=len(payload); mask=os.urandom(4)
  if n<126: h=bytes([0x81,0x80|n])
  elif n<65536: h=bytes([0x81,0xfe])+struct.pack('!H',n)
  else: h=bytes([0x81,0xff])+struct.pack('!Q',n)
  self.s.sendall(h+mask+bytes(v^mask[j%4] for j,v in enumerate(payload))); return self.i
 def recv(self):
  h=recv_exact(self.s,2); n=h[1]&127
  if n==126:n=struct.unpack('!H',recv_exact(self.s,2))[0]
  elif n==127:n=struct.unpack('!Q',recv_exact(self.s,8))[0]
  masked=h[1]&128; mask=recv_exact(self.s,4) if masked else None
  p=recv_exact(self.s,n)
  if masked:p=bytes(v^mask[j%4] for j,v in enumerate(p))
  return json.loads(p)
 def command(self,m,p={}):
  i=self.send(m,p)
  while True:
   x=self.recv()
   if x.get('id')==i:return x

def capture(w,h,name):
 t=new_page('http://localhost:3002'); c=CDP(t['webSocketDebuggerUrl'])
 c.command('Emulation.setDeviceMetricsOverride',{'width':w,'height':h,'deviceScaleFactor':1,'mobile':True})
 time.sleep(1)
 r=c.command('Runtime.evaluate',{'expression':"document.getElementById('beginBtn').click()",'returnByValue':True})
 time.sleep(1.2)
