function openSettings(){showModal(`<div class="modal-card"><button class="modal-close">×</button><div class="modal-kicker">SYSTEM · LOCAL SAVE</div><h2>Settings</h2><p class="modal-desc">Tune the experience for your device. Save data is stored locally in this prototype.</p>${['Music · Orchestral score','Sound effects','Screen shake','High quality effects','Landscape controls'].map((x,i)=>`<div class="setting-row">${x}<div class="toggle ${i<4?'on':''}" data-toggle></div></div>`).join('')}<div class="setting-row setting-editor-row"><span><b>Touch controls</b><small style="display:block;color:#9fb0ad">Drag and reposition every button</small></span><button type="button" id="openControlEditor">EDIT LAYOUT</button></div><button class="modal-action modal-close-action">SAVE SETTINGS &nbsp; →</button></div>`);document.getElementById('openControlEditor')?.addEventListener('click',()=>{closeModal();enterControlEditor()}) }
const controlIds=['move','grapple','jump','dodge','attack','skill','burst'];let savedControlLayout={};try{savedControlLayout=JSON.parse(localStorage.getItem('astra-touch-layout')||'{}')}catch(_){ }
