 const panelData={map:['REGION ATLAS','Lumenwild Frontier','Only places discovered by your own steps appear on the atlas. Activate ancient waypoints to reveal safe routes.',`<div class="map-panel"><div class="map-locked">${state.rift?'RIFT ATTUNED':'UNDISCOVERED · 68%'}</div><div class="map-marker">✦</div><div class="map-label">WHISPERING GLADE</div></div>`],quests:['JOURNAL · MAIN STORY','The Shattered Oath','A resonant pulse calls from the ancient glade. Follow the faint echo to the source, then investigate the strange rift beyond the ruins.',`<div class="modal-tile"><b>01 · Follow the resonance</b><span>Explore Lumenwild and reach the ancient ruins · In progress</span></div><div class="modal-tile"><b>02 · Attune the Veil Rift</b><span>Discover the source of the strange signal · ${state.rift?'Complete':'Undiscovered'}</span></div><div class="modal-tile"><b>03 · Silence the Sentinel</b><span>Defeat Vesper, the Hollow · ${state.phase>=4?'Complete':'Awaiting encounter'}</span></div>`],inventory:['TRAVELER’S PACK','Field Inventory','Collected materials and echoes from your journey. Equipment is earned through play; all story and progression content is available without purchases.',`<div class="modal-tile"><b>✧ Resonance Shards · ${state.save.fragments||0}</b><span>Fragments left behind by defeated echoes</span></div><div class="modal-tile"><b>◈ Wayfarer’s Tonic · 3</b><span>Restores vitality in the field</span></div><div class="modal-tile"><b>✦ Echo · Hollow Wisp</b><span>Captured resonance · Gale affinity</span></div><div class="modal-tile"><b>⚒ Lumen Ore · 12</b><span>A crafting material found in the wild</span></div>`],profile:['WAYFARER PROFILE','Aster · Rank 08','A wanderer awakened at the edge of a fractured sky. Progress is saved locally on this device.',`<div class="modal-tile"><b>EXPEDITION · Lumenwild</b><span>Story ${state.rift?'2':'1'} / 6 · ${state.save.fragments||0} echoes recovered</span></div><div class="modal-tile"><b>THE AETHERBOUND</b><span>Current party · 4 companions · All affinities</span></div>`],menu:['PAUSE MENU','Take a breath, Wayfarer','The frontier will wait for you.',`<div class="modal-grid"><div class="modal-tile"><b>☷ Quest journal</b><span>Review your current objectives</span></div><div class="modal-tile"><b>⌖ Region atlas</b><span>Explore your discovered map</span></div></div>`]};
