  function enterControlEditor(){if(!state.started)return;state.modal=true;state.controlLayoutBefore=JSON.parse(JSON.stringify(savedControlLayout));applyControlLayout(savedControlLayout);document.getElementById('game').classList.add('control-editing');const editor=document.getElementById('controlEditor');editor.classList.add('visible');editor.setAttribute('aria-hidden','false');controlIds.forEach(id=>{const el=document.querySelector(`[data-control-id="${id}"]`);if(!el)return;el.onpointerdown=e=>{if(!document.getElementById('game').classList.contains('control-editing'))return;e.preventDefault();el.setPointerCapture(e.pointerId);el.classList.add('control-custom');el._drag={dx:e.clientX-el.getBoundingClientRect().left-el.offsetWidth/2,dy:e.clientY-el.getBoundingClientRect().top-el.offsetHeight/2}};el.onpointermove=e=>{if(!el._drag)return;e.preventDefault();let r=el.getBoundingClientRect(),cx=e.clientX-el._drag.dx+r.width/2,cy=e.clientY-el._drag.dy+r.height/2;cx=Math.max(r.width/2,Math.min(innerWidth-r.width/2,cx));cy=Math.max(r.height/2,Math.min(innerHeight-r.height/2,cy));el.style.left=(cx/innerWidth*100)+'%';el.style.top=(cy/innerHeight*100)+'%';el.style.right='auto';el.style.bottom='auto'};el.onpointerup=el.onpointercancel=e=>{if(!el._drag)return;el._drag=null;let r=el.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;savedControlLayout[id]={x:cx/innerWidth,y:cy/innerHeight}}})}
  function exitControlEditor(save){const editor=document.getElementById('controlEditor');document.getElementById('game').classList.remove('control-editing');editor.classList.remove('visible');editor.setAttribute('aria-hidden','true');controlIds.forEach(id=>{const el=document.querySelector(`[data-control-id="${id}"]`);if(el){el.onpointerdown=null;el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null;el._drag=null}});if(!save)savedControlLayout=state.controlLayoutBefore||{};applyControlLayout(savedControlLayout);if(save){try{localStorage.setItem('astra-touch-layout',JSON.stringify(savedControlLayout))}catch(_){ }toast('Touch layout saved')}else toast('Layout changes cancelled');state.modal=false}
  document.querySelectorAll('[data-editor-action]').forEach(btn=>btn.addEventListener('click',()=>{const act=btn.dataset.editorAction;if(act==='reset'){savedControlLayout={};applyControlLayout({});toast('Default layout restored')}else if(act==='save')exitControlEditor(true);else exitControlEditor(false)}));applyControlLayout(savedControlLayout);

