.touch-controls{display:none;position:absolute;z-index:5;inset:0;pointer-events:none}
.touch-controls{display:block}


/* Performance + mobile control polish */
.touch-controls{filter:drop-shadow(0 5px 12px rgba(0,0,0,.28))}
.touch-controls{z-index:8}

#game:not(.playing)>.topbar,#game:not(.playing)>.quest-card,#game:not(.playing)>.boss-banner,#game:not(.playing)>.party-panel,#game:not(.playing)>.combat-feed,#game:not(.playing)>.controls-hint,#game:not(.playing)>.touch-controls,#game:not(.playing)>.bottom-hud,#game:not(.playing)>.interaction-prompt,#game:not(.playing)>.world-toast{visibility:hidden}
.control-editing .touch-controls{z-index:25}
.touch-controls.layout-custom .touch-right{position:static;width:0;height:0;transform:none!important}
.stick-zone{position:absolute;left:4vw;bottom:78px;width:118px;height:118px;pointer-events:auto;display:flex;justify-content:center;align-items:center;flex-direction:column}
.stick-zone>span{position:absolute;bottom:-13px;font-size:7px;letter-spacing:.2em;color:#e7e1cf9c}
.stick-zone{bottom:52px;transform:scale(.82);transform-origin:bottom left}
.stick-zone{bottom:62px}
.stick-zone>span{bottom:-17px;font-size:8px;color:#fff6d9;font-weight:700;text-shadow:0 2px 5px #000}
.stick-zone{bottom:58px}
.stick-zone{left:2.5vw;transform:scale(.88);transform-origin:bottom left}
.stick-zone{left:8px;bottom:48px;transform:scale(.75);transform-origin:bottom left}
.stick-zone{bottom:60px}

